  "minimal-ukrainian.lino": "natural:\n  id: minimal-ukrainian\n  label: 'Minimal Ukrainian (NSM semantic primes)'\n  extends: ukrainian\n  profile: minimal-english\n  source: 'https://en.wikipedia.org/wiki/Natural_semantic_metalanguage'\n  true: правда\n  false: неправда\n  templates:\n    function: 'Так хтось робить {name} з {parameters}'\n    function-without-parameters: 'Так хтось робить {name}'\n    declare: 'Є {name}, це {value}'\n    assign: 'Після цього {name} є {value}'\n    print-line: 'Сказати {value} в одному рядку'\n    print: 'Сказати {value}'\n    return-value: 'Відповіддю є {value}'\n    return: 'Зупинитися тут'\n    nothing: 'Нічого не робити'\n    evaluate: 'Зробити {expression}'\n    if: 'Якщо {condition}, зробити це'\n    else-if: 'Якщо ні, якщо {condition}, зробити це'\n    else: 'Якщо ні, зробити це'\n    while: 'Коли {condition}, робити це багато разів'\n    for: 'Для всіх {variable} від {start} до {last}, зробити це'\n    call-without-arguments: '{callee} ( )'\n    equal: '{left} є тим самим що {right}'\n    not-equal: '{left} не є тим самим що {right}'\n    less: '{left} менше ніж {right}'\n    less-or-equal: '{left} не більше ніж {right}'\n    greater: '{left} більше ніж {right}'\n    greater-or-equal: '{left} не менше ніж {right}'\n    array: 'ці речі ({elements})'\n    new-array: '{length} речей як {fill}'\n    element: 'частина {index} з {array}'\n    length: 'скільки частин має {array}'\n    set-element: 'Після цього частина {index} з {name} є {value}'\n  rules:\n    primes: ukrainian\n    extra-words: з в рядку відповіддю зупинитися нічого ні разів для від і або протилежне ніж менше плюс мінус помножити поділити на за модулем неправда скільки має\n",
  "minimal-urdu.lino": "natural:\n  id: minimal-urdu\n  label: 'Minimal Urdu (NSM semantic primes)'\n  extends: urdu\n  profile: minimal-english\n  source: 'https://en.wikipedia.org/wiki/Natural_semantic_metalanguage'\n  templates:\n    function: 'کوئی {parameters} کے ساتھ {name} ایسے کرتا ہے'\n    function-without-parameters: 'کوئی {name} ایسے کرتا ہے'\n    declare: 'ایک {name} ہے، یہ ہے {value}'\n    assign: 'اس کے بعد {name} اب {value} ہے'\n    print-line: '{value} ایک سطر میں کہیں'\n    print: '{value} کہیں'\n    return-value: 'جواب ہے {value}'\n    return: 'یہاں رکیں'\n    nothing: 'کچھ نہ کریں'\n    evaluate: '{expression} کریں'\n    if: 'اگر {condition} تو یہ کریں'\n    else-if: 'اگر ایسا نہیں ہے تو اگر {condition} تو یہ کریں'\n    else: 'اگر ایسا نہیں ہے تو یہ کریں'\n    while: 'جب {condition} تب یہ بہت بار کریں'\n    for: 'ہر {variable} کے لیے {start} سے {last} تک یہ کریں'\n    join: '{left} پھر {right}'\n    equal: '{left} وہی ہے جو {right} ہے'\n    not-equal: '{left} وہی نہیں ہے جو {right} ہے'\n    less: '{left} {right} سے کم ہے'\n    less-or-equal: '{left} {right} سے زیادہ نہیں ہے'\n    greater: '{left} {right} سے زیادہ ہے'\n    greater-or-equal: '{left} {right} سے کم نہیں ہے'\n    array: 'یہ چیزیں ({elements})'\n    new-array: '{length} چیزیں {fill} جیسی'\n    element: '{array} کا حصہ {index}'\n    length: '{array} میں کتنے حصے ہیں'\n    set-element: 'اس کے بعد {name} کا حصہ {index} اب {value} ہے'\n  rules:\n    primes: urdu\n    extra-words: کے ساتھ جو میں سطر جواب رکیں تو بار تب لیے سے تک پھر کا کتنے یا اور جمع تفریق ضرب تقسیم ماڈیولو منفی جھوٹ",
